CREATE OR REPLACE FUNCTION vehicle_performance_score(
    brake_wear REAL,
    track_wear DOUBLE PRECISION,
    vehicle_speed REAL,
    engine_load REAL
) RETURNS NUMERIC AS $$
BEGIN
    RETURN ROUND(CAST((1 - (brake_wear + track_wear)/200.0) * (vehicle_speed/50.0) * (engine_load/100.0) AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

